Object.assign(areaIntros,{"오사카":["OSAKA","먹거리 골목과 성곽, 전망대와 근교 자연을 권역별로 나누어 즐길 수 있는 지역입니다."],"난바·도톤보리":["NAMBA · DOTONBORI","운하의 네온과 시장 골목을 함께 즐길 수 있는 지역입니다. 낮에는 시장을, 저녁에는 강변을 걸어보세요."],"우메다·나카노시마":["UMEDA · NAKANOSHIMA","전망대와 강변 공원, 신사의 전통을 철도로 연결해 둘러볼 수 있는 지역입니다."],"오사카성·다니마치":["OSAKA CASTLE · TANIMACHI","성곽 공원과 역사 전시를 함께 둘러볼 수 있는 지역입니다. 공원 안 이동에도 여유를 두세요."],"덴노지·신세카이":["TENNOJI · SHINSEKAI","사찰과 옛 번화가, 높은 전망대를 한 권역에서 함께 즐길 수 있는 지역입니다."],"오사카 베이":["OSAKA BAY","수족관과 테마파크를 즐길 수 있는 지역입니다. USJ는 다른 명소와 무리하게 묶지 마세요."],"스이타·엑스포":["SUITA · EXPO PARK","태양의 탑과 넓은 공원을 여유롭게 둘러보기 좋은 지역입니다."],"미노오":["MINOH","폭포 산책과 다루마 사찰을 함께 즐길 수 있는 지역입니다. 두 곳 사이는 별도 교통편이 필요합니다."],"스미요시·사카이":["SUMIYOSHI · SAKAI","오래된 신사와 고분의 풍경을 함께 만날 수 있는 지역입니다. 사카이 시내 이동은 따로 고려하세요."],"기시와다·린쿠":["KISHIWADA · RINKU","성하 마을과 공항 맞은편 바닷가를 함께 둘러볼 수 있는 지역입니다. 항공편 시간에는 여유를 두세요."],"이케다":["IKEDA","인스턴트 라멘의 발상지에서 식문화와 발명 이야기를 체험할 수 있는 오사카 북부 지역입니다."]});
